public void testNoCopiesAvailable() throws Exception {
    MockBookieClient bookieClient = spy(new MockBookieClient(executor));
    MockLedgerStorage storage = spy(new MockLedgerStorage());
    long ledgerId = 0xbeeb;
    LedgerMetadata metadata = LedgerMetadataBuilder.create().withId(ledgerId).withPassword(new byte[0]).withDigestType(DigestType.CRC32C).withEnsembleSize(1).withWriteQuorumSize(1).withAckQuorumSize(1).newEnsembleEntry(0, Lists.newArrayList(bookie1)).withLastEntryId(10).withLength(1000).withClosedState().build();
