@Test
public void testBuildBookieServerCustomComponents() throws Exception {
    ServerConfiguration serverConf = new ServerConfiguration().setAllowLoopback(true).setAutoRecoveryDaemonEnabled(false).setHttpServerEnabled(false).setExtraServerComponents(new String[] { TestComponent.class.getName() });
    BookieConfiguration conf = new BookieConfiguration(serverConf);
    StatsProvider statsProvider = new NullStatsProvider();
    StatsLogger rootStatsLogger = statsProvider.getStatsLogger("");
    RegistrationManager registrationManager = new NullRegistrationManager();
    LedgerManagerFactory ledgerManagerFactory = new NullLedgerManagerFactory();
    DiskChecker diskChecker = BookieResources.createDiskChecker(serverConf);
    LedgerDirsManager ledgerDirsManager = BookieResources.createLedgerDirsManager(conf.getServerConf(), diskChecker, rootStatsLogger.scope(LD_LEDGER_SCOPE));
    LedgerDirsManager indexDirsManager = BookieResources.createIndexDirsManager(conf.getServerConf(), diskChecker, rootStatsLogger.scope(LD_INDEX_SCOPE), ledgerDirsManager);
    UncleanShutdownDetectionImpl uncleanShutdownDetection = new UncleanShutdownDetectionImpl(ledgerDirsManager);
    ByteBufAllocatorWithOomHandler byteBufFromResources = mock(ByteBufAllocatorWithOomHandler.class);
    ByteBufAllocatorWithOomHandler byteBuf = mock(ByteBufAllocatorWithOomHandler.class);
    @Cleanup
    MockedStatic<BookieResources> bookieResourcesMockedStatic = mockStatic(BookieResources.class);
    bookieResourcesMockedStatic.when(() -> BookieResources.createMetadataDriver(any(), any())).thenReturn(new NullMetadataBookieDriver());
    bookieResourcesMockedStatic.when(() -> BookieResources.createAllocator(any())).thenReturn(byteBufFromResources);
    @Cleanup
    MockedStatic<LegacyCookieValidation> legacyCookieValidationMockedStatic = mockStatic(LegacyCookieValidation.class);
    legacyCookieValidationMockedStatic.when(() -> LegacyCookieValidation.newLegacyCookieValidation(any(), any())).thenReturn(mock(LegacyCookieValidation.class));
    @Cleanup
    MockedStatic<BookieImpl> bookieMockedStatic = mockStatic(BookieImpl.class, CALLS_REAL_METHODS);
    bookieMockedStatic.when(() -> BookieImpl.newBookieImpl(any(), any(), any(), any(), any(), any(), any(), any(), any())).thenReturn(mock(BookieImpl.class));
    BookieServer mockServer = mock(BookieServer.class);
    @Cleanup
    MockedStatic<BookieServer> bookieServerMockedStatic = mockStatic(BookieServer.class);
    bookieServerMockedStatic.when(() -> BookieServer.newBookieServer(any(), any(), any(), any(), any())).thenReturn(mockServer);
    BookieSocketAddress bookieAddress = new BookieSocketAddress("127.0.0.1", 1281);
    when(mockServer.getLocalAddress()).thenReturn(bookieAddress);
    EmbeddedServer server = EmbeddedServer.builder(conf).statsProvider(statsProvider).registrationManager(registrationManager).ledgerManagerFactory(ledgerManagerFactory).diskChecker(diskChecker).ledgerDirsManager(ledgerDirsManager).indexDirsManager(indexDirsManager).allocator(byteBuf).uncleanShutdownDetection(uncleanShutdownDetection).build();
    assertSame(statsProvider, server.getStatsProvider());
    assertSame(registrationManager, server.getRegistrationManager());
    assertSame(ledgerManagerFactory, server.getLedgerManagerFactory());
    assertSame(diskChecker, server.getDiskChecker());
    assertSame(ledgerDirsManager, server.getLedgerDirsManager());
    assertSame(indexDirsManager, server.getIndexDirsManager());
    LifecycleComponentStack stack = server.getLifecycleComponentStack();
    assertEquals(3, stack.getNumComponents());
    assertTrue(stack.getComponent(2) instanceof TestComponent);
    stack.start();
    verify(mockServer, times(1)).start();
    stack.stop();
    stack.close();
    verify(mockServer, times(1)).shutdown();
}

