    BookieImpl.checkDirectoryStructure(BookieImpl.getCurrentDirectory(journalDir));
    ServerConfiguration conf = TestBKConfiguration.newServerConfiguration().setJournalDirName(journalDir.getPath()).setMetadataServiceUri(null).setJournalAdaptiveGroupWrites(false).setJournalSyncData(true).setJournalPageCacheFlushIntervalMSec(5000);
    LedgerDirsManager ledgerDirsManager = mock(LedgerDirsManager.class);
    Journal journal = new Journal(0, journalDir, conf, ledgerDirsManager);
    CountDownLatch forceWriteThreadSuspendedLatch = new CountDownLatch(1);
    BatchedArrayBlockingQueue<ForceWriteRequest> supportQueue = enableForceWriteThreadSuspension(forceWriteThreadSuspendedLatch, journal);
    journal = spy(journal);
    JournalChannel jc = spy(new JournalChannel(journalDir, 1));
    doReturn(jc).when(journal).newLogFile(anyLong(), nullable(Long.class));
    journal.start();
    LogMark lastLogMarkBeforeWrite = journal.getLastLogMark().markLog().getCurMark();
    CountDownLatch latch = new CountDownLatch(1);
